// Props: Poly Haven (CC0) models converted to BUSHED's high-resolution pixel-art look with lowpix
// (games/bushed/tools/convert_props.py). Real-world scale in metres, origin at the centre of the x/z bounds and
// y = 0 at the lowest point, front facing +Z. Each glb has a root node named after the prop with children
// `body` (opaque), and optionally `glass` (transparent) and `flame` (emissive card).
//
//   const axe = await loadProp('wooden_axe');      // a fresh clone (geometry + materials shared)
//   PROP_META.wooden_axe.mass                      // kg
//
// PROP_META is generated from the actual .glb files by games/bushed/tools/gen_prop_meta.py: do not hand-edit
// the block between the markers (edit the tables in the generator and re-run it).
import * as THREE from 'three';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { applyPixelTex } from '../gfx/tex';

export type PropCategory = 'tool' | 'light' | 'cabin' | 'storage' | 'outdoor' | 'store';

export interface PropMeta {
  name: string;
  category: PropCategory;
  /** kg, realistic */
  mass: number;
  /** [x, y, z] metres, measured from the glb */
  size: [number, number, number];
  collider: 'box' | 'hull';
  /** flat xyz list (<= 32 points) of a convex hull in the prop's local space (only for collider 'hull') */
  hull?: number[];
  /** general-store price in dollars (only things the store sells) */
  price?: number;
  desc?: string;
  /** triangle count of the glb */
  tris: number;
  /** local position of the light source (lamps, lanterns, flashlights) */
  light?: [number, number, number];
  /** mean roughness of the source material */
  rough: number;
  /** the CC0 source page */
  source: string;
}

