export type PropId = string;

const loader = new GLTFLoader();
const cache = new Map<string, Promise<THREE.Object3D>>();

/** URL of a prop's glb (relative to the page, like every asset) */
export function propUrl(id: PropId): string {
  return `assets/models/${id}.glb`;
}

function convertMaterial(src: THREE.Material, kind: string): THREE.Material {
  const s = src as THREE.MeshStandardMaterial;
  const map = s.map ?? null;
  if (map) applyPixelTex(map, { srgb: true });
  if (kind === 'glass') {
    return new THREE.MeshStandardMaterial({
      name: s.name, color: s.color.clone(), map, roughness: 0.1, metalness: 0,
      transparent: true, opacity: 0.28, depthWrite: false, side: THREE.DoubleSide,
    });
  }
  if (kind === 'flame') {
    return new THREE.MeshStandardMaterial({
      name: s.name, map, color: 0xffffff, emissive: new THREE.Color(1.0, 0.75, 0.45), emissiveMap: map,
      emissiveIntensity: 2.0, transparent: true, opacity: 0.9, depthWrite: false, side: THREE.DoubleSide,
    });
  }
  // body: opaque pixel-art atlas, lit by the scene (no baked light in the colour map)
  return new THREE.MeshStandardMaterial({
    name: s.name, map, roughness: s.roughness ?? 0.85, metalness: 0, side: THREE.DoubleSide,
  });
}

function prepare(root: THREE.Object3D, id: PropId): THREE.Object3D {
  const done = new Map<THREE.Material, THREE.Material>();
  root.name = id;
  root.traverse((o) => {
    const m = o as THREE.Mesh;
    if (!m.isMesh) return;
    const kind = (o.name === 'glass' || o.name === 'flame') ? o.name
      : ((Array.isArray(m.material) ? m.material[0] : m.material).userData?.kind as string | undefined) ?? 'body';
    const conv = (mat: THREE.Material) => {
      let c = done.get(mat);
      if (!c) { c = convertMaterial(mat, kind); done.set(mat, c); mat.dispose(); }
      return c;
    };
    m.material = Array.isArray(m.material) ? m.material.map(conv) : conv(m.material);
    const opaque = kind === 'body';
    m.castShadow = opaque;
    m.receiveShadow = true;
    if (!opaque) m.renderOrder = 1;
  });
  root.userData.propId = id;
  root.userData.meta = PROP_META[id];
  return root;
}

/** Load a prop (cached); every call returns a new clone that shares geometry and materials. */
export function loadProp(id: PropId): Promise<THREE.Object3D> {
  let p = cache.get(id);
  if (!p) {
    p = loader.loadAsync(propUrl(id)).then((g) => prepare(g.scene, id));
    cache.set(id, p);
    p.catch(() => cache.delete(id));
  }
  return p.then((o) => {
    const c = o.clone(true);
    c.userData = { ...o.userData };
    return c;
  });
}

/** Start loading several props without waiting (warm the cache). */
export function preloadProps(ids: PropId[]): Promise<void> {
  return Promise.all(ids.map((id) => loadProp(id))).then(() => undefined);
}

/** every prop id that has a glb */
export function propIds(): PropId[] {
  return Object.keys(PROP_META);
}
